"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

const MESSAGES = ["Build succeeded", "New comment on your PR", "Deployed to production", "3 new stars"];

export function NotificationStackTailwind({ duration = 3000 }) {
  const [items, setItems] = useState<{ id: number; text: string }[]>([]);
  const next = useRef(0);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  useEffect(() => () => timers.current.forEach(clearTimeout), []);
  const dismiss = (id: number) => setItems((l) => l.filter((x) => x.id !== id));
  const add = () => {
    const id = next.current++;
    setItems((l) => [{ id, text: MESSAGES[id % MESSAGES.length] }, ...l].slice(0, 4));
    timers.current.push(setTimeout(() => dismiss(id), duration));
  };
  return (
    <div className="flex w-72 flex-col items-center gap-3">
      <button type="button" onClick={add} className="rounded-lg bg-zinc-100 px-5 py-2 text-sm font-medium text-zinc-950">Notify me</button>
      <ul aria-live="polite" className="flex w-full flex-col gap-2">
        <AnimatePresence initial={false}>
          {items.map((it) => (
            <motion.li key={it.id} layout initial={{ opacity: 0, y: -20, scale: 0.92 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, x: 80 }} transition={{ type: "spring", stiffness: 400, damping: 30 }} className="flex items-center gap-3 rounded-2xl border border-zinc-800 bg-zinc-900 px-4 py-3 text-sm text-zinc-100">
              <span className="flex-1">{it.text}</span>
              <button type="button" aria-label={`Dismiss: ${it.text}`} onClick={() => dismiss(it.id)} className="text-zinc-500 hover:text-zinc-100">×</button>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </div>
  );
}
